  public void Initialize(){if(initialized)return;initialized=true;Live=GetComponent<Stage47Preview>();CameraStudy=GetComponent<Stage49Preview>();CameraStudy.enabled=false;CameraStudy.normalOverlay=CameraStudy.combatOverlay=CameraStudy.rangeOverlay=CameraStudy.cellOverlay=false;Live.stage48Optimized=true;Live.automation=false;Live.showUI=false;Live.ExternalInputBlock=true;Live.worldSize=192;Live.speed=speed;Live.showContours=true;
