  public static Color[] SurfacePixels(AuthoredCamp definition){var pixels=new Color[192*192];for(int y=0;y<192;y++)for(int x=0;x<192;x++)pixels[y*192+x]=definition.Protected(x,y)?Color.white:Color.black;return pixels;}
  void RefreshSurface(){if(surface==null||ReferenceEquals(surfaceDefinition,Session.Definition))return;surface.SetPixels(SurfacePixels(Session.Definition));surface.Apply();surfaceDefinition=Session.Definition;}
  void Bind(){Session.Committed+=OnBatch;}
