  public void ResetTest(int selected=0){Initialize();long t=System.Diagnostics.Stopwatch.GetTimestamp();Session.Committed-=OnBatch;Session=NewSession();ConstructionClock=new CampConstructionPreview(Session);Live.ReplacePreviewWorld(Session.BindReadOnlyGeometry());RefreshSurface();Live.Actors.Clear();Bind();AcceptedBatches=ChangedCells=0;ConstructionReplay.Clear();showReservations=selected==5;pendingDeath=selected>=6;pendingPublic=selected==7;if(selected>=1)Session.FakeReturn(1,5,2);if(selected==2)Session.BeginConstruction(out _);if(selected>=3){ConstructionClock.BuildTarget=selected==3?5:10;ConstructionClock.BuildDorm=true;}Go(arrival==0?"arrival.first":"run.departure");ResetMs=StreamingGeometry.Elapsed(t);Status="Restored comparison state "+selected+". Homes advance through bounded construction.";}
  public void SetFraming(int n){framing=n;CameraStudy.Apply(2);Live.settings.anchor=n==0?.62f:.57f;}
  public void Go(string id){var m=Session.Definition.Marker(id);if(!Session.Active(m.Gate)&&id!="bones"&&id!="shop.reserved"){Status=m.Name+" is locked or reserved.";return;}Live.Teleport(V(m.Interaction));Live.SetPreviewFocus(Live.Position);}
  public void SimulateArrival(){if(arrival==3&&(Session.Deaths==0||Session.Living==0)){Status="Post-death arrival scenario needs a test death and a living Buddy; real succession is not connected.";return;}Go(arrival==0?"arrival.first":"run.departure");Status=new[]{"Intro approach only; no new story sequence","Continue scenario; current session retained, no slot loaded","Return arrival scenario; use Fake Return for expedition inputs","Post-death arrival position only; real succession unconnected"}[arrival];}
  public void FakeReturn(){if(Constructing){Status="Finish construction before returning";return;}Session.FakeReturn(returnBuddies,returnMushrooms,returnShinies);arrival=1;Go("run.departure");Status=$"Preview return: +{returnBuddies} Buddies, +{returnMushrooms} mushrooms, +{returnShinies} shinies. No run or save invoked.";}
