  public int Dig(Point2 target){if(!WorldInputAllowed)return 0;if(Vector2.Distance(Live.Position,V(target))>2.2f)return 0;var cells=new List<DualTile>();for(int y=(int)target.Y-1;y<=(int)target.Y+1;y++)for(int x=(int)target.X-1;x<=(int)target.X+1;x++)cells.Add(new DualTile(x,y));return Session.DigPlayer(cells);}
  void Update(){Initialize();Live.Actors.Clear();Live.speed=speed;if(automation)return;var k=Keyboard.current;var m=Mouse.current;if(k!=null&&k.tabKey.wasPressedThisFrame)showPanel=!showPanel;bool over=showPanel&&m!=null&&m.position.ReadValue().x<335;var availability=SporeInputContextRouter.GetAvailability(PreviewInputContext);var movement=k==null||!availability.Move||PauseSimulation?Vector2.zero:new Vector2((k.dKey.isPressed?1:0)-(k.aKey.isPressed?1:0),(k.sKey.isPressed?1:0)-(k.wKey.isPressed?1:0));Vector2 aim=Live.Aim;if(m!=null&&Live.Snapshot!=null&&!over&&availability.Aim&&!PauseSimulation){var p=Live.previewCamera.ScreenToWorldPoint(new Vector3(m.position.ReadValue().x,m.position.ReadValue().y,10));aim=V(Live.Snapshot.Unproject(new Point2(p.x,-p.y)))-Live.Position;}if(Live.Ready&&!PauseSimulation&&Time.timeScale>0){var next=Session.Move(P(Live.Position),new Point2(movement.normalized.x*speed*Time.deltaTime,movement.normalized.y*speed*Time.deltaTime),1);Live.TeleportWithoutFocus(V(next));if(aim.sqrMagnitude>.001)Live.Aim=aim.normalized;digTimer-=Time.deltaTime;if(WorldInputAllowed&&!over&&digTimer<=0&&((m!=null&&m.leftButton.isPressed)||(k!=null&&k.spaceKey.isPressed))){int n=Dig(P(Live.Position+Live.Aim*1.6f));Status=n>0?$"Excavated{n} authorized expansion cells":"Only ordinary expansion dirt accepts player digging. Bedrooms belong to Buddy construction.";digTimer=.15f;}if(WorldInputAllowed&&k!=null&&k.eKey.wasPressedThisFrame)Interact();}TickResidents(Math.Min(.05,Time.deltaTime));}
  public void TickResidents(double dt){if(PauseSimulation||Time.timeScale<=0||dt<=0||PreviewInputContext==SporeInputContext.Pause)return;using(GeometryTrace.Measure(GeometryPhase.Construction)){Session.TickSocialMovement(dt);if(Constructing||ConstructionClock.BuildDorm){ConstructionClock.Tick(dt);Status=string.IsNullOrEmpty(ConstructionClock.Status)?"Buddy moving along the validated dorm route...":ConstructionClock.Status;}if(!Constructing&&!ConstructionClock.BuildDorm&&Session.Established==10){if(pendingDeath){Session.BuddyDied();pendingDeath=false;}if(pendingPublic){Session.Advance();Session.Advance();pendingPublic=false;}}}}
  public string Interact(){if(!WorldInputAllowed)return Status="World actions blocked by preview input context.";CampMarker nearest=null;double best=2.4;foreach(var m in Session.Definition.Markers){double d=Vector2.Distance(Live.Position,V(m.Interaction));if(d<best&&Session.Active(m.Gate)){nearest=m;best=d;}}if(nearest==null)return Status="Move to a station's small interaction marker and press E.";switch(nearest.Id){case "run.departure":return Status="Run departure is not connected in this test. Leader/successor eligibility remains a production integration gap.";case "fire":Session.Discover();Session.Recover();return Status="Preview Fire visit: recovered flag set; real healing, food, upgrades and saves are not connected.";case "squad":foreach(var r in Session.Residents)if(r.Alive){r.InSquad=!r.InSquad;return Status=r.Id+" preview squad="+r.InSquad+". Production roster UI is unconnected.";}break;case "bones":return Status="Preview memorial: "+Session.Deaths+" fallen Buddy records; succession is unconnected.";case "storage":return Status=$"Preview storage: {Session.Mushrooms} mushrooms / {Session.Shinies} shinies. No campaign resources.";}return Status=nearest.Name+"  /  preview marker only";}
  Batch Add(string name,string color,int order){var go=new GameObject("Stage57 "+name){hideFlags=HideFlags.DontSave};go.transform.SetParent(transform,false);var f=go.AddComponent<MeshFilter>();f.sharedMesh=new Mesh{name=go.name,hideFlags=HideFlags.DontSave};var rr=go.AddComponent<MeshRenderer>();var mat=new Material(Live.materials[(int)PreviewLayer.Gobbo]){hideFlags=HideFlags.DontSave};mat.SetColor("_Color",palette.Color(color));owned.Add(mat);rr.sharedMaterial=mat;rr.sortingOrder=order;var b=new Batch{Data=new PreviewMeshData(name,PreviewLayer.Gobbo),Filter=f,Renderer=rr};batches.Add(b);return b;}
